import re

class IPAddress:
    MAX_OCTET_VALUE = 255
    OCTET_COUNT = 4
    OCTET_PATTERN = re.compile(r'^\d{1,3}$')

    def __init__(self, ip_address):
        self._ip_address = ip_address

    @property
    def ip_address(self):
        return self._ip_address

    @ip_address.setter
    def ip_address(self, value):
        self._ip_address = value

    def is_valid(self):
        if not self._has_correct_octet_count():
            return False
        return all(self._is_valid_octet(octet) for octet in self._get_octets_raw())

    def _has_correct_octet_count(self):
        return len(self._get_octets_raw()) == self.OCTET_COUNT

    def _is_valid_octet(self, octet):
        if not self.OCTET_PATTERN.match(octet):
            return False
        value = int(octet)
        return 0 <= value <= self.MAX_OCTET_VALUE

    def _get_octets_raw(self):
        return self._ip_address.split('.')

    def get_octets(self):
        if not self.is_valid():
            return []
        return list(self._get_octets_raw())

    def get_binary(self):
        if not self.is_valid():
            return ''
        return '.'.join(self._octet_to_binary(octet) for octet in self._get_octets_raw())

    @staticmethod
    def _octet_to_binary(octet):
        return format(int(octet), '08b')
